.chart-wrap{position:relative;min-height:231px}.chart-legend{font-size:10px;color:#8e8994;display:flex;gap:16px;align-items:center;margin-top:11px}.legend-dot{display:inline-block;width:8px;height:8px;background:var(--pink);border-radius:3px;margin-right:6px}.legend-dot.light{background:#ffc0d6}.chart-svg{display:block;width:100%;height:auto;max-height:253px;overflow:visible;stroke:none}.donut-wrap{display:flex;align-items:center;justify-content:center;gap:20px;padding:6px 0 13px}.donut{position:relative;width:174px;height:174px;flex-shrink:0}.donut svg{width:100%;height:100%;stroke:none}.donut-hole{position:absolute;inset:31px;background:#fff;border-radius:100%;display:flex;flex-direction:column;align-items:center;justify-content:center}.donut-total{font-size:29px;font-weight:850;line-height:1}.donut-label{font-size:10px;color:#a19aa6;margin-top:7px}.donut-legend{flex:1;min-width:0}.donut-line{display:flex;justify-content:space-between;gap:10px;margin-bottom:13px;font-size:11px}.donut-line span:first-child{color:#797380}.donut-line strong{font-size:12px;font-weight:800}.donut-line i{width:8px;height:8px;border-radius:3px;display:inline-block;margin-right:6px}
.bottom-grid{display:grid;grid-template-columns:minmax(0,1.62fr) minmax(320px,.96fr);gap:18px}.table-wrap{overflow-x:auto}.tbl{width:100%;border-collapse:collapse;text-align:left;font-size:12px}.tbl th{background:#fcfafc;color:#9e97a3;font-size:10px;letter-spacing:.5px;text-transform:uppercase;font-weight:800;padding:12px 14px;border-bottom:1px solid var(--line);white-space:nowrap}.tbl td{padding:14px;border-bottom:1px solid #f2eff3;vertical-align:middle}.tbl tbody tr:last-child td{border-bottom:0}.tbl tbody tr:hover{background:#fffafc}.strong{font-weight:750;color:#47404d}.small{font-size:11px;color:#aaa3ad;margin-top:3px}.mono{font:11px ui-monospace,SFMono-Regular,Consolas,monospace}.badge{font-size:10px;display:inline-flex;align-items:center;gap:5px;border-radius:6px;padding:5px 8px;font-weight:750;white-space:nowrap;background:#f3f2f4;color:#807987}.badge:before{content:"";background:currentColor;height:5px;width:5px;border-radius:50%}.badge.green{background:#eaf8f2;color:#2b8b68}.badge.pink{background:#fff0f5;color:#c2346c}.badge.amber{background:#fff5e7;color:#a77a25}.badge.blue{background:#edf3ff;color:#4975b7}.badge.red{background:#fff0f3;color:#be455a}.quick-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.quick-action{background:#fff;border:1px solid #eeeaf0;border-radius:10px;padding:15px 11px;display:flex;gap:10px;align-items:center;text-align:left;min-height:76px;color:#4e4756}.quick-action:hover{background:#fff8fb;border-color:#f4cfdd}.quick-icon{background:#fff0f6;color:#d93c74;width:37px;height:37px;border-radius:10px;display:grid;place-items:center}.quick-action strong{font-size:11px;display:block}.quick-action small{font-size:10px;color:#9d96a1;display:block;margin-top:5px}.callout{margin-top:15px;background:#fff8fa;border:1px solid #f9e3eb;border-radius:9px;padding:13px 14px;font-size:11px;color:#997286;line-height:1.7}.callout strong{color:#b83a69}.section-actions{display:flex;align-items:center;gap:9px;justify-content:space-between;flex-wrap:wrap;margin-bottom:16px}.filter-set{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.field,.select{height:39px;border:1px solid #eae6ed;border-radius:9px;background:#fff;color:#605b68;padding:0 12px;outline:none;min-width:145px;font-size:12px}.select{cursor:pointer}.field:focus,.select:focus,.textarea:focus{border-color:#e78cae}.search-field{min-width:245px}.filter-label{font-size:11px;color:#96909b}.table-card{overflow:hidden}.table-top{padding:19px 21px 14px}.table-count{color:#9b96a2;font-size:11px;margin:0}.btn-link{border:0;background:transparent;color:#d43970;font-size:11px;font-weight:800;padding:4px 5px}.btn-link:hover{text-decoration:underline}.btn-link.danger{color:#b44b59}.inline-actions{display:flex;align-items:center;gap:5px}.user-avatar{width:33px;height:33px;border-radius:50%;display:grid;place-items:center;background:#fce4ed;color:#aa3567;font-size:10px;font-weight:850}.user-line{display:flex;align-items:center;gap:10px}.pagination-hint{padding:13px 20px;color:#a099a6;font-size:11px;border-top:1px solid #f0edf2}.empty{padding:45px 16px;text-align:center;color:#89818f}.empty svg{width:30px;height:30px;color:#c9c2cc;margin-bottom:9px}
