.overlay{position:fixed;inset:0;background:rgba(31,22,38,.47);z-index:80;display:flex;align-items:center;justify-content:center;padding:18px}.modal{background:white;border-radius:15px;max-width:660px;width:100%;max-height:min(91vh,930px);overflow:auto;box-shadow:0 27px 80px rgba(23,10,35,.2)}.modal-head{padding:20px 24px;border-bottom:1px solid #f0ebf0;display:flex;align-items:flex-start;justify-content:space-between}.modal-title{font-size:18px;font-weight:800;margin:0}.modal-desc{font-size:11px;color:#9a939e;margin:5px 0 0}.modal-body{padding:23px 24px}.modal-foot{border-top:1px solid #f0ebf0;padding:16px 24px;display:flex;justify-content:flex-end;gap:9px}.icon-close{border:0;background:transparent;color:#9e97a4;padding:3px}.toast-host{position:fixed;bottom:22px;right:23px;z-index:150;display:flex;flex-direction:column;gap:8px;max-width:360px}.toast{background:#332c3a;color:white;border-radius:10px;padding:12px 16px;box-shadow:0 9px 25px #32233333;font-size:12px;line-height:1.5}.shade{display:none}
