 </aside>
 <div class="main">
  <header class="topbar">
   <div style="display:flex;align-items:center;gap:12px"><button id="menu-toggle" class="top-icon menu-toggle" aria-label="Mở menu"><svg><use href="#i-menu"/></svg></button><div class="crumb">BookVerse <span style="padding:0 8px">/</span> <strong id="crumb">Tổng quan</strong></div></div>
   <div class="top-right"><label class="global-search"><svg><use href="#i-search"/></svg><input type="search" id="global-search" placeholder="Tìm người dùng, voucher..." aria-label="Tìm trong hệ thống"></label><button class="top-icon" id="alerts" aria-label="Thông báo hệ thống" title="Thông báo hệ thống"><svg><use href="#i-bell"/></svg><span class="dot"></span></button><div class="profile"><div class="avatar">QT</div><div class="profile-info"><div class="profile-name">Quản trị viên</div><div class="profile-sub">Quyền quản trị hệ thống</div></div></div></div>
  </header>
