<div id="modal-root"></div><div class="toast-host" id="toast-host" role="status" aria-live="polite"></div>
<script>
(()=>{
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"></use></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n||0).toLocaleString('vi-VN')+'đ';
const compact=n=>Number(n||0).toLocaleString('vi-VN');
const newId=(prefix,arr)=>prefix+String(Math.max(0,...arr.map(x=>Number(x.id.replace(/\D/g,''))||0))+1).padStart(3,'0');
// Dữ liệu giả lập; không đại diện cho tình hình kinh doanh thực tế.
let users=[
 {id:'ND001',name:'Nguyễn Minh Anh',email:'minhanh@example.com',phone:'0900000001',role:'KHACH_HANG',position:'',status:'active',joined:'2026-10-20'},
 {id:'ND002',name:'Trần Quốc Bảo',email:'quocbao@example.com',phone:'0900000002',role:'NHAN_VIEN',position:'Kho sách',status:'active',joined:'2026-10-18'},
 {id:'ND003',name:'Lê Thùy Linh',email:'thuylinh@example.com',phone:'0900000003',role:'KHACH_HANG',position:'',status:'active',joined:'2026-10-26'},
 {id:'ND004',name:'Phạm Gia Huy',email:'giahuy@example.com',phone:'0900000004',role:'NHAN_VIEN',position:'Xử lý đơn',status:'active',joined:'2026-10-12'},
 {id:'ND005',name:'Vũ Khánh Ngọc',email:'khanhngoc@example.com',phone:'0900000005',role:'KHACH_HANG',position:'',status:'locked',joined:'2026-10-08'},
 {id:'ND006',name:'Hoàng Mai Chi',email:'maichi@example.com',phone:'0900000006',role:'KHACH_HANG',position:'',status:'active',joined:'2026-10-29'},
 {id:'ND007',name:'Đỗ Tuấn Kiệt',email:'tuankiet@example.com',phone:'0900000007',role:'NHAN_VIEN',position:'Kho sách',status:'active',joined:'2026-10-16'},
 {id:'ND008',name:'Đặng Hồng Phúc',email:'hongphuc@example.com',phone:'0900000008',role:'QUAN_TRI_VIEN',position:'',status:'active',joined:'2026-10-01'}
];
const currentAdmin='ND008';
let vouchers=[
 {id:'VC001',code:'SACHMOI20',name:'Ưu đãi khách hàng mới',type:'percent',value:20,min:200000,max:50000,usage:86,limit:200,start:'2026-10-20',end:'2026-12-31',enabled:true},
 {id:'VC002',code:'BOOK30K',name:'Giảm 30K cho đơn từ 199K',type:'fixed',value:30000,min:199000,max:30000,usage:121,limit:300,start:'2026-10-01',end:'2026-11-30',enabled:true},
 {id:'VC003',code:'FREESHIP25',name:'Hỗ trợ phí vận chuyển',type:'fixed',value:25000,min:250000,max:25000,usage:157,limit:400,start:'2026-10-01',end:'2026-12-31',enabled:true},
 {id:'VC004',code:'THANG11',name:'Chào tháng sách mới',type:'percent',value:15,min:300000,max:60000,usage:0,limit:250,start:'2026-11-05',end:'2026-11-30',enabled:true},
 {id:'VC005',code:'SALE10',name:'Giảm 10% đơn hàng',type:'percent',value:10,min:100000,max:30000,usage:200,limit:200,start:'2026-09-01',end:'2026-10-20',enabled:false}
];
const perms=[
 {key:'view-dashboard',title:'Xem bảng tổng quan',roles:['NHAN_VIEN','QUAN_TRI_VIEN']},
 {key:'catalog',title:'Quản lý sách và tồn kho',roles:['NHAN_VIEN','QUAN_TRI_VIEN']},
 {key:'orders',title:'Xử lý đơn hàng',roles:['NHAN_VIEN','QUAN_TRI_VIEN']},
 {key:'users',title:'Quản lý tài khoản người dùng',roles:['QUAN_TRI_VIEN']},
 {key:'permissions',title:'Cấp và thay đổi quyền',roles:['QUAN_TRI_VIEN']},
 {key:'vouchers',title:'Tạo và cấu hình voucher',roles:['QUAN_TRI_VIEN']},
 {key:'reports',title:'Xem báo cáo và xuất thống kê',roles:['QUAN_TRI_VIEN']}
];
const roleLabels={KHACH_HANG:'Khách hàng',NHAN_VIEN:'Nhân viên',QUAN_TRI_VIEN:'Quản trị viên'};
const permissionRoles=['KHACH_HANG','NHAN_VIEN','QUAN_TRI_VIEN'];
let audit=[
 {at:'01/11/2026 09:25',action:'Thay đổi trạng thái voucher BOOK30K',by:'QT001',type:'ticket'},
 {at:'31/10/2026 16:12',action:'Khóa tài khoản ND005',by:'QT001',type:'lock'},
 {at:'31/10/2026 14:40',action:'Xem báo cáo doanh thu tháng 10',by:'QT001',type:'chart'},
 {at:'30/10/2026 11:06',action:'Thêm tài khoản nhân viên ND007',by:'QT001',type:'users'}
];
const revenue={week:{labels:['T2','T3','T4','T5','T6','T7','CN'],current:[9,12,10,14,13,17,16],previous:[7,8,9,10,10,12,11],unit:'triệu đồng'},month:{labels:['01-05','06-10','11-15','16-20','21-25','26-31'],current:[38,46,55,49,64,70],previous:[35,38,43,45,53,56],unit:'triệu đồng'},year:{labels:['T1','T2','T3','T4','T5','T6','T7','T8','T9','T10','T11','T12'],current:[42,48,51,59,63,68,73,82,89,104,112,118],previous:[35,37,44,48,51,57,62,68,73,81,88,97],unit:'triệu đồng'}};
const ordersSummary=[{label:'Hoàn thành',value:278,color:'#e55b8f'},{label:'Đang giao',value:67,color:'#eea1be'},{label:'Chờ xử lý',value:31,color:'#f3d1df'},{label:'Hủy / hoàn',value:14,color:'#ddd9e5'}];
const bestBooks=[{title:'Nhà giả kim',units:95},{title:'Thói quen nguyên tử',units:78},{title:'Cây cam ngọt của tôi',units:64},{title:'Đắc nhân tâm',units:51}];
let view='overview', period='month', userSearch='',userRole='',userStatus='',voucherSearch='',voucherStatus='';
const viewNames={overview:'Tổng quan',users:'Quản lý người dùng',roles:'Vai trò & phân quyền',vouchers:'Voucher & ưu đãi',reports:'Báo cáo tổng hợp',audit:'Nhật ký hoạt động'};
const stat=(label,value,sub,i,tone)=>`<div class="card stat"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${tone}">${icon(i)}</span></div><div class="stat-number">${value}</div><div class="stat-foot">${sub}</div></div>`;
const badge=(text,tone)=>`<span class="badge ${tone}">${esc(text)}</span>`;
const getStatusVoucher=v=>{let now='2026-11-01';return !v.enabled?'paused':(v.usage>=v.limit||v.end<now?'expired':v.start>now?'upcoming':'active')};
const statusVoucherUI=s=>({active:badge('Đang áp dụng','green'),paused:badge('Tạm dừng','red'),expired:badge('Đã kết thúc','amber'),upcoming:badge('Sắp diễn ra','blue')})[s];
const header=(title,sub,actions='')=>`<div class="header-row"><div><div class="eyebrow">TRUNG TÂM QUẢN TRỊ BOOKVERSE</div><h1 class="page-title">${title}</h1><p class="page-sub">${sub}</p></div><div class="header-actions">${actions}</div></div>`;
const button=(text,action,primary=false,ico='')=>`<button class="btn ${primary?'btn-primary':''}" data-action="${action}">${ico?icon(ico):''}${text}</button>`;
const baseStats=()=>[
 stat('Tài khoản trong bản mẫu',compact(users.length),'<span class="trend">●</span> Đang quản lý', 'users','pink'),
 stat('Nhân viên',compact(users.filter(u=>u.role==='NHAN_VIEN').length),'2 nhóm nghiệp vụ', 'shield','blue'),
 stat('Voucher đang áp dụng',compact(vouchers.filter(v=>getStatusVoucher(v)==='active').length),'Trong thời hạn sử dụng','ticket','amber'),
 stat('Doanh thu tháng mẫu','322,0 tr','<span class="trend">↑ 12,8%</span> so với tháng trước','chart','green')
].join('');
function lineChart(p=period){const data=revenue[p],W=710,H=240,L=46,R=17,T=18,B=43,aw=W-L-R,ah=H-T-B,max=Math.ceil(Math.max(...data.current,...data.previous)*1.13/10)*10,n=data.labels.length;
 const xx=i=>L+(n===1?aw/2:i*aw/(n-1)),yy=v=>T+ah*(1-v/max);
 const grid=[0,.25,.5,.75,1].map(t=>`<line x1="${L}" y1="${(T+ah*(1-t)).toFixed(1)}" x2="${W-R}" y2="${(T+ah*(1-t)).toFixed(1)}" stroke="#f0edf2" stroke-dasharray="3 4"/><text x="${L-13}" y="${(T+ah*(1-t)+4).toFixed(1)}" text-anchor="end" font-size="11" fill="#aaa3ae">${Math.round(max*t)}</text>`).join('');
 const points=values=>values.map((v,i)=>`${xx(i).toFixed(1)},${yy(v).toFixed(1)}`).join(' ');
 const area=data.current.map((v,i)=>`${i===0?'M':'L'}${xx(i).toFixed(1)} ${yy(v).toFixed(1)}`).join(' ')+` L${xx(n-1)} ${T+ah} L${xx(0)} ${T+ah} Z`;
 return `<div class="chart-wrap"><svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Biểu đồ doanh thu minh họa theo ${p}"><defs><linearGradient id="pink-area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#e96296" stop-opacity=".2"/><stop offset="1" stop-color="#e96296" stop-opacity="0"/></linearGradient></defs>${grid}<path d="${area}" fill="url(#pink-area)"/><polyline points="${points(data.previous)}" stroke="#efb3c9" stroke-width="3" stroke-dasharray="6 6" fill="none" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${points(data.current)}" stroke="#db3b76" stroke-width="3.4" fill="none" stroke-linecap="round" stroke-linejoin="round"/>${data.current.map((v,i)=>`<circle cx="${xx(i)}" cy="${yy(v)}" r="4.4" fill="#fff" stroke="#da3c76" stroke-width="2.4"><title>${esc(data.labels[i])}: ${v} triệu đồng (minh họa)</title></circle>`).join('')}${data.labels.map((x,i)=>`<text x="${xx(i)}" y="${H-16}" text-anchor="middle" font-size="11" fill="#9b94a0">${esc(x)}</text>`).join('')}</svg></div><div class="chart-legend"><span><i class="legend-dot"></i>Kỳ đang xem</span><span><i class="legend-dot light"></i>Kỳ so sánh</span><span style="margin-left:auto">Đơn vị: triệu đồng · Dữ liệu mẫu</span></div>`;
}
function chartToggle(){return `<div class="pill-switch" aria-label="Khoảng thời gian"><button data-period="week" class="${period==='week'?'active':''}">7 ngày</button><button data-period="month" class="${period==='month'?'active':''}">30 ngày</button><button data-period="year" class="${period==='year'?'active':''}">12 tháng</button></div>`;}
function donut(){const total=ordersSummary.reduce((s,i)=>s+i.value,0);let offset=0;const pieces=ordersSummary.map(x=>{const angle=360*x.value/total;const start=offset;offset+=angle;return `${x.color} ${start.toFixed(2)}deg ${offset.toFixed(2)}deg`}).join(',');return `<div class="donut-wrap"><div class="donut" style="border-radius:50%;background:conic-gradient(${pieces})"><div class="donut-hole"><div class="donut-total">${total}</div><div class="donut-label">Đơn hàng mẫu</div></div></div><div class="donut-legend">${ordersSummary.map(x=>`<div class="donut-line"><span><i style="background:${x.color}"></i>${x.label}</span><strong>${x.value}</strong></div>`).join('')}</div></div>`;}
function overview(){return header('Bảng điều khiển','Chủ nhật, 01 tháng 11 năm 2026 · Theo dõi tình hình hoạt động của BookVerse.',button('Xuất báo cáo','export-report',false,'download'))+`<div class="stat-grid">${baseStats()}</div><div class="overview-grid"><section class="card pad"><div class="panel-head"><div><h2 class="panel-title">Doanh thu bán sách</h2><p class="panel-desc">So sánh hiệu quả kinh doanh theo kỳ (dữ liệu minh họa)</p></div>${chartToggle()}</div>${lineChart()}</section><section class="card pad"><div class="panel-head"><div><h2 class="panel-title">Tình trạng đơn hàng</h2><p class="panel-desc">Tổng hợp các trạng thái xử lý</p></div><button class="link" data-view="reports">Chi tiết ${icon('chevron')}</button></div>${donut()}<div class="callout"><strong>Thông tin quản trị</strong> · Các số liệu doanh thu và đơn hàng là dữ liệu mô phỏng, không lấy từ website thực tế.</div></section></div><div class="bottom-grid"><section class="card pad"><div class="panel-head"><div><h2 class="panel-title">Tài khoản gần đây</h2><p class="panel-desc">Danh sách người dùng trong bản mẫu</p></div><button data-view="users" class="link">Xem tất cả ${icon('chevron')}</button></div><div class="table-wrap"><table class="tbl"><thead><tr><th>Họ tên</th><th>Vai trò</th><th>Ngày tham gia</th><th>Trạng thái</th></tr></thead><tbody>${[...users].sort((a,b)=>b.joined.localeCompare(a.joined)).slice(0,5).map(u=>`<tr><td><div class="strong">${esc(u.name)}</div><div class="small">${esc(u.email)}</div></td><td>${esc(roleLabels[u.role])}</td><td>${dateVi(u.joined)}</td><td>${u.status==='active'?badge('Hoạt động','green'):badge('Đã khóa','red')}</td></tr>`).join('')}</tbody></table></div></section><section class="card pad"><div class="panel-head"><div><h2 class="panel-title">Truy cập nhanh</h2><p class="panel-desc">Những công việc quản trị thường dùng</p></div></div><div class="quick-grid"><button class="quick-action" data-action="add-user"><span class="quick-icon">${icon('users')}</span><span><strong>Thêm người dùng</strong><small>Cấp tài khoản mới</small></span></button><button class="quick-action" data-view="roles"><span class="quick-icon">${icon('shield')}</span><span><strong>Phân quyền</strong><small>Điều chỉnh quyền hạn</small></span></button><button class="quick-action" data-action="add-voucher"><span class="quick-icon">${icon('ticket')}</span><span><strong>Tạo voucher</strong><small>Thiết lập ưu đãi</small></span></button><button class="quick-action" data-view="reports"><span class="quick-icon">${icon('chart')}</span><span><strong>Xem báo cáo</strong><small>Thống kê tổng hợp</small></span></button></div><div class="callout"><strong>Lưu ý phân quyền:</strong> Vai trò quản trị được quản lý riêng; quyền của nhân viên kho và nhân viên xử lý đơn cần kiểm tra tại máy chủ.</div></section></div>`;}
function dateVi(s){if(!s)return '—';const a=s.split('-');return a.length===3?`${a[2]}/${a[1]}/${a[0]}`:s;}
function userFiltered(){return users.filter(u=>(!userRole||u.role===userRole)&&(!userStatus||u.status===userStatus)&&(!userSearch||(`${u.id} ${u.name} ${u.email} ${u.phone} ${u.position}`).toLowerCase().includes(userSearch.toLowerCase())))}
function usersPage(){const filtered=userFiltered();return header('Quản lý người dùng','Tìm kiếm, thêm, sửa và kiểm soát trạng thái tài khoản khách hàng, nhân viên và quản trị viên.',button('Thêm người dùng','add-user',true,'plus'))+`<section class="card table-card"><div class="table-top"><div class="section-actions"><div class="filter-set"><input class="field search-field" id="user-search" placeholder="Tìm mã, tên, email..." value="${esc(userSearch)}" aria-label="Tìm người dùng"><select class="select" id="user-role" aria-label="Lọc vai trò"><option value="">Tất cả vai trò</option>${permissionRoles.map(k=>`<option value="${k}" ${userRole===k?'selected':''}>${roleLabels[k]}</option>`).join('')}</select><select class="select" id="user-status" aria-label="Lọc trạng thái"><option value="">Tất cả trạng thái</option><option value="active" ${userStatus==='active'?'selected':''}>Hoạt động</option><option value="locked" ${userStatus==='locked'?'selected':''}>Đã khóa</option></select></div><span class="table-count" id="user-count">${filtered.length} tài khoản</span></div></div><div class="table-wrap"><table class="tbl"><thead><tr><th>Người dùng</th><th>Mã</th><th>Vai trò</th><th>Ngày tạo</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody id="user-rows">${userRows(filtered)}</tbody></table></div><div class="pagination-hint">Dữ liệu mẫu · Chỉ tài khoản có quyền mới được thay đổi vai trò hoặc khóa người dùng.</div></section>`;}
function userRows(arr){return arr.length?arr.map(u=>`<tr><td><div class="user-line"><div class="user-avatar">${esc(u.name.split(' ').slice(-2).map(x=>x[0]).join(''))}</div><div><div class="strong">${esc(u.name)}</div><div class="small">${esc(u.email)}</div></div></div></td><td class="mono">${esc(u.id)}</td><td><div>${esc(roleLabels[u.role])}</div>${u.position?`<div class="small">${esc(u.position)}</div>`:''}</td><td>${dateVi(u.joined)}</td><td>${u.status==='active'?badge('Hoạt động','green'):badge('Đã khóa','red')}</td><td><div class="inline-actions"><button class="btn-link" data-action="edit-user" data-id="${u.id}">Sửa</button><button class="btn-link ${u.status==='active'?'danger':''}" data-action="toggle-user" data-id="${u.id}" ${u.id===currentAdmin?'disabled title="Không thể khóa tài khoản quản trị đang sử dụng"':''}>${u.status==='active'?'Khóa':'Mở khóa'}</button></div></td></tr>`).join(''):`<tr><td colspan="6" class="empty">Không tìm thấy tài khoản phù hợp.</td></tr>`;}
function rolePage(){return header('Vai trò & phân quyền','Cấu hình quyền truy cập dựa trên vai trò. Quyền trong bản mẫu chỉ là minh họa.',button('Lưu thay đổi','save-roles',true,'check'))+`<div class="role-list">${[{name:'KHACH_HANG',desc:'Mua sách, quản lý giỏ hàng và theo dõi đơn hàng.',symbol:'users'},{name:'NHAN_VIEN',desc:'Quản lý nghiệp vụ sách, kho hàng hoặc xử lý đơn tùy chức vụ.',symbol:'setting'},{name:'QUAN_TRI_VIEN',desc:'Quản lý tài khoản, phân quyền, voucher và báo cáo.',symbol:'shield'}].map(r=>`<article class="card role-item"><div class="role-top"><span class="role-mark">${icon(r.symbol)}</span><h3>${roleLabels[r.name]}</h3></div><p>${r.desc}</p><div class="role-count">${users.filter(u=>u.role===r.name).length} tài khoản trong bản mẫu</div></article>`).join('')}</div><section class="card pad"><div class="panel-head"><div><h2 class="panel-title">Ma trận phân quyền</h2><p class="panel-desc">Bật/tắt quyền truy cập cho từng vai trò (không thay đổi quyền quản trị cốt lõi).</p></div>${badge('Chưa lưu vào DB','amber')}</div><div class="table-wrap"><table class="matrix"><thead><tr><th>Quyền / chức năng</th><th>Khách hàng</th><th>Nhân viên</th><th>Quản trị viên</th></tr></thead><tbody>${perms.map(p=>`<tr><td><span class="strong">${p.title}</span></td>${permissionRoles.map(r=>`<td><input class="permission-check" type="checkbox" data-perm="${p.key}" data-role="${r}" ${p.roles.includes(r)?'checked':''} ${r==='QUAN_TRI_VIEN'||(r==='KHACH_HANG'&&['users','permissions','vouchers','reports','orders','catalog'].includes(p.key))?'disabled':''} aria-label="${p.title} cho ${roleLabels[r]}"></td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="perm-note">Trong hệ thống thật, ma trận quyền được lưu trong cơ sở dữ liệu và thực thi qua middleware/policy Laravel. Với nhân viên, nên có phân quyền nghiệp vụ chi tiết: quản lý sách/kho và xử lý đơn hàng, thay vì mặc định mọi nhân viên đều được phép làm tất cả.</p></section>`;}
function voucherFiltered(){return vouchers.filter(v=>(!voucherSearch||(`${v.code} ${v.name}`).toLowerCase().includes(voucherSearch.toLowerCase()))&&(!voucherStatus||getStatusVoucher(v)===voucherStatus))}
function vouchersPage(){const arr=voucherFiltered();return header('Quản lý voucher','Thiết lập mã giảm giá, điều kiện áp dụng, số lượt sử dụng và thời hạn.',button('Tạo voucher mới','add-voucher',true,'plus'))+`<section class="card table-card"><div class="table-top"><div class="section-actions"><div class="filter-set"><input class="field search-field" placeholder="Tìm mã giảm giá..." id="voucher-search" value="${esc(voucherSearch)}"><select id="voucher-status" class="select" aria-label="Lọc trạng thái voucher"><option value="">Tất cả trạng thái</option><option value="active" ${voucherStatus==='active'?'selected':''}>Đang áp dụng</option><option value="upcoming" ${voucherStatus==='upcoming'?'selected':''}>Sắp diễn ra</option><option value="paused" ${voucherStatus==='paused'?'selected':''}>Tạm dừng</option><option value="expired" ${voucherStatus==='expired'?'selected':''}>Đã kết thúc</option></select></div><span class="table-count" id="voucher-count">${arr.length} voucher</span></div></div><div class="table-wrap"><table class="tbl"><thead><tr><th>Mã và tên ưu đãi</th><th>Mức giảm</th><th>Điều kiện</th><th>Đã sử dụng</th><th>Thời hạn</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody id="voucher-rows">${voucherRows(arr)}</tbody></table></div><div class="pagination-hint">Các mã giảm giá và số lượt đã sử dụng đều là dữ liệu minh họa.</div></section>`;}
function voucherRows(arr){return arr.length?arr.map(v=>`<tr><td><div class="voucher-code">${esc(v.code)}</div><div class="voucher-meta">${esc(v.name)}</div></td><td class="strong">${v.type==='percent'?v.value+'%':money(v.value)}</td><td><div>Từ ${money(v.min)}</div><div class="small">Tối đa ${money(v.max)}</div></td><td><div class="progress-line"><span style="width:${Math.min(100,Math.round(v.usage/v.limit*100))}%"></span></div><span class="small">${v.usage}/${v.limit} lượt</span></td><td><div>${dateVi(v.start)}</div><div class="small">đến ${dateVi(v.end)}</div></td><td>${statusVoucherUI(getStatusVoucher(v))}</td><td><div class="inline-actions"><button class="btn-link" data-action="edit-voucher" data-id="${v.id}">Sửa</button><button class="btn-link ${v.enabled?'danger':''}" data-action="toggle-voucher" data-id="${v.id}">${v.enabled?'Tạm dừng':'Bật lại'}</button></div></td></tr>`).join(''):`<tr><td colspan="7" class="empty">Không tìm thấy voucher phù hợp.</td></tr>`;}
function reportsPage(){return header('Báo cáo tổng hợp','Phân tích doanh thu, đơn hàng và các đầu sách bán chạy theo kỳ (dữ liệu mô phỏng).',button('Xuất CSV','export-report',true,'download'))+`<div class="report-details"><div class="detail-tile"><small>Doanh thu kỳ báo cáo</small><b>322.000.000đ</b></div><div class="detail-tile"><small>Đơn hoàn thành</small><b>278 đơn</b></div><div class="detail-tile"><small>Tỷ lệ hủy / hoàn</small><b>3,6%</b></div></div><div class="report-grid"><section class="card pad"><div class="panel-head"><div><h2 class="panel-title">Xu hướng doanh thu</h2><p class="panel-desc">Thay đổi khoảng thời gian để so sánh</p></div>${chartToggle()}</div>${lineChart()}</section><section class="card pad"><div class="panel-head"><div><h2 class="panel-title">Đầu sách bán chạy</h2><p class="panel-desc">Xếp hạng mẫu theo số lượng bán</p></div></div><div class="best-list">${bestBooks.map((b,i)=>`<div class="best-row"><div class="best-rank">${i+1}</div><div class="best-info"><div class="best-title">${esc(b.title)}</div><div class="best-bar"><span style="width:${Math.round(b.units/bestBooks[0].units*100)}%"></span></div></div><div class="best-amount">${b.units} cuốn</div></div>`).join('')}</div><div class="callout">Báo cáo sử dụng số liệu mô phỏng. Bản thực tế sẽ thống kê từ các bảng đơn hàng, chi tiết đơn hàng và thanh toán đã được xác nhận.</div></section></div><section class="card pad"><div class="panel-head"><div><h2 class="panel-title">Tổng hợp trạng thái đơn hàng</h2><p class="panel-desc">Phục vụ phân tích hiệu quả vận hành</p></div></div><div class="table-wrap"><table class="tbl"><thead><tr><th>Trạng thái</th><th>Số đơn</th><th>Tỷ trọng</th></tr></thead><tbody>${ordersSummary.map(x=>`<tr><td><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${x.color};margin-right:8px"></span>${x.label}</td><td class="strong">${x.value}</td><td>${(100*x.value/390).toFixed(1).replace('.',',')}%</td></tr>`).join('')}</tbody></table></div></section>`;}
function auditPage(){return header('Nhật ký hoạt động','Theo dõi những tác vụ quản trị quan trọng trong bản mẫu.',button('Xuất nhật ký CSV','export-audit',false,'download'))+`<section class="card pad"><div class="panel-head"><div><h2 class="panel-title">Lịch sử thao tác</h2><p class="panel-desc">Các tác vụ gần đây được ghi lại trong phiên mô phỏng.</p></div>${badge('Bản demo','blue')}</div><div class="activity">${audit.map(a=>`<div class="activity-row"><div class="activity-dot">${icon(a.type)}</div><div><div class="activity-main"><strong>${esc(a.action)}</strong></div><div class="activity-date">${esc(a.at)} · Thực hiện bởi ${esc(a.by)}</div></div></div>`).join('')}</div></section>`;}
function render(){const pages={overview,users:usersPage,roles:rolePage,vouchers:vouchersPage,reports:reportsPage,audit:auditPage};$('#crumb').textContent=viewNames[view];$('#page-content').innerHTML='';$('#page-header').innerHTML='';const temp=document.createElement('div');temp.innerHTML=pages[view]();$('#page-header').append(temp.firstElementChild);while(temp.firstChild)$('#page-content').append(temp.firstChild);$$('[data-view].nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#nav-vouchers').textContent=vouchers.filter(v=>getStatusVoucher(v)==='active').length;}
function navigate(v){if(!(v in viewNames))return;view=v;userSearch='';userRole='';userStatus='';voucherSearch='';voucherStatus='';render();$('#sidebar').classList.remove('open');$('#shade').classList.remove('show');window.scrollTo({top:0,behavior:'auto'});}
function toast(message){const box=document.createElement('div');box.className='toast';box.textContent=message;$('#toast-host').append(box);setTimeout(()=>box.remove(),3700);}
function log(action,type='activity'){audit.unshift({at:new Date().toLocaleString('vi-VN',{hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit',year:'numeric'}),action,by:'QT001',type});}
function modal(title,desc,content,onSubmit,submit='Lưu thay đổi'){const root=$('#modal-root');root.innerHTML=`<div class="overlay" id="overlay"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><h2 class="modal-title">${esc(title)}</h2><p class="modal-desc">${esc(desc)}</p></div><button class="icon-close" type="button" data-action="close-modal" aria-label="Đóng">${icon('close')}</button></div><form id="dialog-form"><div class="modal-body">${content}</div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Hủy</button><button type="submit" class="btn btn-primary">${esc(submit)}</button></div></form></div></div>`;$('#dialog-form').addEventListener('submit',e=>{e.preventDefault();onSubmit(new FormData(e.currentTarget));});}
function closeModal(){$('#modal-root').innerHTML='';}
function userDialog(id){const existing=users.find(u=>u.id===id),u=existing||{name:'',email:'',phone:'',role:'KHACH_HANG',position:'',status:'active'};const field=(label,name,type='text',value='',req='')=>`<div class="form-group"><label class="form-label" for="f-${name}">${label}</label><input id="f-${name}" class="form-control" name="${name}" type="${type}" value="${esc(value)}" ${req}></div>`;
const html=`<div class="form-grid">${field('Họ và tên','name','text',u.name,'required minlength="2"')}${field('Email','email','email',u.email,'required')}${field('Số điện thoại','phone','tel',u.phone,'required pattern="[0-9+ -]{9,16}"')}<div class="form-group"><label class="form-label" for="f-role">Vai trò</label><select class="form-control" id="f-role" name="role" ${id===currentAdmin?'disabled':''}>${permissionRoles.map(k=>`<option value="${k}" ${u.role===k?'selected':''}>${roleLabels[k]}</option>`).join('')}</select></div><div class="form-group"><label class="form-label" for="f-position">Chức vụ nhân viên</label><select class="form-control" id="f-position" name="position"><option value="">Không áp dụng</option><option ${u.position==='Kho sách'?'selected':''}>Kho sách</option><option ${u.position==='Xử lý đơn'?'selected':''}>Xử lý đơn</option></select><div class="form-help">Chỉ dùng khi vai trò là Nhân viên</div></div><div class="form-group"><label class="form-label" for="f-status">Trạng thái</label><select id="f-status" class="form-control" name="status" ${id===currentAdmin?'disabled':''}><option value="active" ${u.status==='active'?'selected':''}>Hoạt động</option><option value="locked" ${u.status==='locked'?'selected':''}>Khóa</option></select></div></div><p class="form-help" style="margin:15px 0 0">Bản mẫu không tạo mật khẩu thật, không gửi thông báo email và không lưu dữ liệu vào cơ sở dữ liệu.</p>`;
 modal(existing?'Chỉnh sửa tài khoản':'Thêm người dùng','Quản lý thông tin tài khoản BookVerse',html,fd=>{const value=Object.fromEntries(fd),email=value.email.trim().toLowerCase();if(users.some(x=>x.email.toLowerCase()===email&&x.id!==id)){toast('Email đã được sử dụng trong dữ liệu mẫu.');return;}if(value.role==='NHAN_VIEN'&&!value.position){toast('Vui lòng chọn chức vụ cho nhân viên.');return;}if(value.role!=='NHAN_VIEN')value.position='';if(existing){Object.assign(existing,{...value,email,role:id===currentAdmin?'QUAN_TRI_VIEN':value.role,status:id===currentAdmin?'active':value.status});log(`Cập nhật tài khoản ${id}`,'users');toast('Đã cập nhật tài khoản trong phiên demo.')}else{const idNew=newId('ND',users);users.unshift({...value,email,id:idNew,joined:'2026-11-01'});log(`Tạo tài khoản ${idNew}`,'users');toast('Đã thêm tài khoản vào dữ liệu mẫu.')}closeModal();render();});}
function voucherDialog(id){const existing=vouchers.find(v=>v.id===id),v=existing||{code:'',name:'',type:'percent',value:10,min:0,max:50000,limit:100,start:'2026-11-01',end:'2026-12-31',usage:0,enabled:true};const inp=(name,label,type,value,attrs='')=>`<div class="form-group"><label for="v-${name}" class="form-label">${label}</label><input class="form-control" id="v-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;
const html=`<div class="form-grid">${inp('code','Mã voucher','text',v.code,'required maxlength="24" pattern="[A-Za-z0-9_-]+"')}${inp('name','Tên chương trình','text',v.name,'required maxlength="100"')}<div class="form-group"><label class="form-label">Loại giảm giá</label><select class="form-control" name="type"><option value="percent" ${v.type==='percent'?'selected':''}>Giảm theo phần trăm</option><option value="fixed" ${v.type==='fixed'?'selected':''}>Giảm tiền cố định</option></select></div>${inp('value','Giá trị giảm (%, hoặc đồng)','number',v.value,'required min="1"')}${inp('min','Giá trị đơn tối thiểu (đ)','number',v.min,'required min="0"')}${inp('max','Mức giảm tối đa (đ)','number',v.max,'required min="1"')}${inp('limit','Giới hạn lượt sử dụng','number',v.limit,'required min="1"')}${inp('start','Ngày bắt đầu','date',v.start,'required')}${inp('end','Ngày kết thúc','date',v.end,'required')}<div class="form-group"><label class="form-label">Trạng thái</label><select class="form-control" name="enabled"><option value="true" ${v.enabled?'selected':''}>Bật voucher</option><option value="false" ${!v.enabled?'selected':''}>Tạm dừng</option></select></div></div>`;
modal(existing?'Chỉnh sửa voucher':'Tạo voucher mới','Cấu hình điều kiện áp dụng và giới hạn sử dụng',html,fd=>{const f=Object.fromEntries(fd),record={code:f.code.trim().toUpperCase(),name:f.name.trim(),type:f.type,value:Number(f.value),min:Number(f.min),max:Number(f.max),limit:Number(f.limit),start:f.start,end:f.end,enabled:f.enabled==='true'};
if(record.start>record.end){toast('Ngày kết thúc phải sau hoặc bằng ngày bắt đầu.');return;}if(record.type==='percent'&&record.value>100){toast('Giá trị giảm phần trăm không được vượt 100%.');return;}if(vouchers.some(x=>x.code===record.code&&x.id!==id)){toast('Mã voucher đã tồn tại trong bản mẫu.');return;}if(existing&&record.limit<existing.usage){toast('Số lượt tối đa không được nhỏ hơn số lượt đã dùng.');return;}if(existing){Object.assign(existing,record);log(`Cập nhật voucher ${record.code}`,'ticket');toast('Đã cập nhật voucher trong phiên demo.')}else{const newCode=newId('VC',vouchers);vouchers.unshift({...record,id:newCode,usage:0});log(`Tạo voucher ${record.code}`,'ticket');toast('Đã tạo voucher mẫu.')}closeModal();render();});}
function confirmDialog(title,msg,onYes,positive='Xác nhận'){modal(title,'Hãy kiểm tra thao tác trước khi tiếp tục',`<p style="line-height:1.7;color:#67606d;margin:0">${esc(msg)}</p>`,()=>{closeModal();onYes();},positive);}
function saveCSV(filename,lines){const safe=v=>`"${String(v??'').replace(/"/g,'""')}"`;const content='\ufeff'+lines.map(row=>row.map(safe).join(',')).join('\r\n');const blob=new Blob([content],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportReport(){saveCSV('bookverse-bao-cao-minh-hoa.csv',[['Mục','Giá trị','Ghi chú'],['Doanh thu kỳ mẫu',322000000,'Không phải số liệu thực'],['Đơn hoàn thành',278,'Dữ liệu mẫu'],['Đơn đang giao',67,'Dữ liệu mẫu'],['Đơn chờ xử lý',31,'Dữ liệu mẫu'],['Đơn hủy/hoàn',14,'Dữ liệu mẫu'],...bestBooks.map(b=>['Sách bán chạy: '+b.title,b.units,'Số cuốn minh họa'])]);toast('Đã xuất CSV dữ liệu mẫu.');}
function syncFilters(e){const id=e.target.id;if(id==='user-search'){userSearch=e.target.value;const a=userFiltered();$('#user-rows').innerHTML=userRows(a);$('#user-count').textContent=a.length+' tài khoản';}else if(id==='user-role'||id==='user-status'){userRole=$('#user-role').value;userStatus=$('#user-status').value;const a=userFiltered();$('#user-rows').innerHTML=userRows(a);$('#user-count').textContent=a.length+' tài khoản';}else if(id==='voucher-search'){voucherSearch=e.target.value;const a=voucherFiltered();$('#voucher-rows').innerHTML=voucherRows(a);$('#voucher-count').textContent=a.length+' voucher';}else if(id==='voucher-status'){voucherStatus=e.target.value;const a=voucherFiltered();$('#voucher-rows').innerHTML=voucherRows(a);$('#voucher-count').textContent=a.length+' voucher';}}
function handleAction(btn){const action=btn.dataset.action,id=btn.dataset.id;if(action==='close-modal')return closeModal();if(action==='add-user'||action==='edit-user')return userDialog(action==='edit-user'?id:null);if(action==='toggle-user'){const u=users.find(x=>x.id===id);if(!u||id===currentAdmin)return;const isActive=u.status==='active';return confirmDialog(isActive?'Khóa tài khoản':'Mở khóa tài khoản',`${isActive?'Khóa':'Mở khóa'} tài khoản ${u.name} (${u.id})?`,()=>{u.status=isActive?'locked':'active';log(`${isActive?'Khóa':'Mở khóa'} tài khoản ${u.id}`,'lock');render();toast('Đã thay đổi trạng thái tài khoản (demo).')});}
if(action==='add-voucher'||action==='edit-voucher')return voucherDialog(action==='edit-voucher'?id:null);
if(action==='toggle-voucher'){const v=vouchers.find(x=>x.id===id);if(!v)return;return confirmDialog(v.enabled?'Tạm dừng voucher':'Kích hoạt lại voucher',`Bạn muốn ${v.enabled?'tạm dừng':'bật lại'} mã ${v.code}?`,()=>{v.enabled=!v.enabled;log(`${v.enabled?'Kích hoạt':'Tạm dừng'} voucher ${v.code}`,'ticket');render();toast('Đã thay đổi trạng thái voucher (demo).')});}
if(action==='save-roles'){log('Lưu cấu hình phân quyền mẫu','shield');toast('Đã lưu ma trận quyền trong phiên demo (không cập nhật MySQL).');return;}
if(action==='export-report')return exportReport();if(action==='export-audit'){saveCSV('bookverse-nhat-ky-demo.csv',[['Thời gian','Hành động','Người thực hiện'],...audit.map(a=>[a.at,a.action,a.by])]);toast('Đã xuất nhật ký mẫu.');}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){navigate(nav.dataset.view);return;}const periodBtn=e.target.closest('[data-period]');if(periodBtn){period=periodBtn.dataset.period;render();return;}const action=e.target.closest('[data-action]');if(action){handleAction(action);return;}if(e.target.id==='overlay')closeModal();});
document.addEventListener('input',e=>{if(['user-search','voucher-search'].includes(e.target.id))syncFilters(e)});
document.addEventListener('change',e=>{if(['user-role','user-status','voucher-status'].includes(e.target.id))syncFilters(e);const p=e.target;if(p.matches('.permission-check')){const perm=perms.find(x=>x.key===p.dataset.perm);if(perm){const role=p.dataset.role;perm.roles=perm.roles.filter(r=>r!==role);if(p.checked)perm.roles.push(role);}}});
$('#menu-toggle').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#shade').classList.add('show')});$('#shade').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#shade').classList.remove('show')});
$('#alerts').addEventListener('click',()=>{toast(`Trong bản mẫu có ${users.filter(u=>u.status==='locked').length} tài khoản bị khóa và ${vouchers.filter(v=>getStatusVoucher(v)==='upcoming').length} voucher sắp diễn ra.`)});
$('#global-search').addEventListener('keydown',e=>{if(e.key!=='Enter')return;const q=e.target.value.trim();if(!q)return;userSearch=q;navigate('users');userSearch=q;render();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
render();
})();
</script>
</body>
</html>
